from pathlib import Path
import pandas as pd,json,hashlib,collections
H=Path(__file__).resolve().parent

def main():
 base=pd.read_parquet(H/'all1767_native2021_geography_gaps_source_frame.parquet');a=pd.read_parquet(H/'dated_primary_and_geometry_validated_A_candidates_v2.parquet');initial=pd.read_parquet(H/'all1767_native_code_candidate_unknown_ledger.parquet');b=pd.read_parquet(H/'B_dated_exact_parent_source_assertions.parquet');assert a.id.is_unique
 cols=['id','candidate_status','source_osm_node_id','source_lat','source_lon','source_version','source_object_timestamp','unresolved_reasons_json','geometry_status','official_Jan_NP_row1','official_Jan_parent8_row1','official_Jan_parent_header_section']
 out=base.merge(a[cols],on='id',how='left',validate='one_to_one');out['proposed_own_coordinate_source_candidate']=out.candidate_status.fillna('').str.startswith(('A1_validated','A2_validated'));out['recovery_status']='no_validated_own_NP_sourcepoint_yet';out.loc[out.candidate_status.notna(),'recovery_status']='coded_sourcepoint_requires_further_review';out.loc[out.proposed_own_coordinate_source_candidate,'recovery_status']='dated_identity_sourcepoint_candidate_pending_independent_admission';out.loc[out.existing_source_snap_over10km,'recovery_status']='existing_coordinate_over10km_no_threshold_relaxation';out['B_source_assertion_count']=out.id.map(b.groupby('id').size()).fillna(0).astype('int32');out['axis_adopted']=False;out['model_or_route_changed']=False;out['coordinate_measurement_date_unknown']=True;out['coordinate_precision_calibrated']=False;out.to_parquet(H/'all1767_source_recovery_proposal_ledger.parquet',index=False)
 valid=out[out.proposed_own_coordinate_source_candidate];r={'status':'NATIONAL_SOURCE_COORDINATE_RECOVERY_PROPOSAL_NOT_AXIS_ADOPTION','target_NPs':len(out),'missing_coordinates':int(out.coordinate_missing.sum()),'existing_over10km':int(out.existing_source_snap_over10km.sum()),'validated_sourcepoint_candidate_NPs':len(valid),'validated_sourcepoint_missing_NPs':int(valid.coordinate_missing.sum()),'validated_sourcepoint_positive_NPs':int(valid.population_2021.gt(0).sum()),'validated_sourcepoint_population2021':float(valid.population_2021.sum()),'remaining_missing_without_candidate':int((out.coordinate_missing&~out.proposed_own_coordinate_source_candidate).sum()),'remaining_missing_population':float(out.loc[out.coordinate_missing&~out.proposed_own_coordinate_source_candidate,'population_2021'].sum()),'recovery_status_counts':out.recovery_status.value_counts().to_dict(),'source_coordinate_snapshot':'2021-01-01T21:42:03Z','not_measurement_date':True,'no_road_distance_based_coordinate_selection':True,'no_new_coordinate_axis_adopted':True,'no_10km_relaxation':True,'input_and_output_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [H/'dated_primary_and_geometry_validated_A_candidates_v2.parquet',H/'B_dated_exact_parent_source_assertions.parquet',H/'all1767_source_recovery_proposal_ledger.parquet']}};(H/'recovery_proposal_receipt.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');valid.sort_values('population_2021',ascending=False).head(30).to_csv(H/'top30_positive_sourcepoint_candidates.csv',index=False);print(json.dumps(r,ensure_ascii=False))
